<template>
  <div class="page-container">
    <el-row :gutter="20" class="stat-row">
      <el-col :span="6">
        <el-card shadow="hover" class="stat-card">
          <div class="stat-item">
            <i class="el-icon-document" style="color:#409eff;font-size:28px;"></i>
            <div class="stat-content">
              <div class="stat-title">报修总数</div>
              <div class="stat-value">{{ stats.total }}</div>
            </div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card shadow="hover" class="stat-card">
          <div class="stat-item">
            <i class="el-icon-time" style="color:#e6a23c;font-size:28px;"></i>
            <div class="stat-content">
              <div class="stat-title">待处理</div>
              <div class="stat-value">{{ stats.pending }}</div>
            </div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card shadow="hover" class="stat-card">
          <div class="stat-item">
            <i class="el-icon-loading" style="color:#409eff;font-size:28px;"></i>
            <div class="stat-content">
              <div class="stat-title">处理中</div>
              <div class="stat-value">{{ stats.processing }}</div>
            </div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card shadow="hover" class="stat-card">
          <div class="stat-item">
            <i class="el-icon-circle-check" style="color:#67c23a;font-size:28px;"></i>
            <div class="stat-content">
              <div class="stat-title">已完成</div>
              <div class="stat-value">{{ stats.completed }}</div>
            </div>
          </div>
        </el-card>
      </el-col>
    </el-row>

    <el-row :gutter="20" style="margin-top: 20px;">
      <el-col :span="12">
        <el-card shadow="hover">
          <div slot="header"><span>分类统计</span></div>
          <div ref="categoryChartRef" style="height: 300px;"></div>
        </el-card>
      </el-col>
      <el-col :span="12">
        <el-card shadow="hover">
          <div slot="header"><span>优先级统计</span></div>
          <div ref="priorityChartRef" style="height: 300px;"></div>
        </el-card>
      </el-col>
    </el-row>

    <el-card shadow="hover" style="margin-top: 20px;">
      <div slot="header"><span>最近报修</span></div>
      <el-table :data="stats.recent" stripe>
        <el-table-column prop="title" label="标题" />
        <el-table-column prop="status" label="状态" width="100">
          <template slot-scope="{ row }">
            <el-tag :type="statusType[row.status]">{{ statusMap[row.status] }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="priority" label="优先级" width="100">
          <template slot-scope="{ row }">
            <el-tag :type="priorityType[row.priority]">{{ priorityMap[row.priority] }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="created_at" label="报修时间" width="180">
          <template slot-scope="{ row }">{{ formatDate(row.created_at) }}</template>
        </el-table-column>
      </el-table>
    </el-card>
  </div>
</template>

<script>
import * as echarts from 'echarts'
import { maintenanceApi } from '../../api'

export default {
  name: 'DashboardView',
  data() {
    return {
      stats: {
        total: 0, pending: 0, processing: 0, completed: 0,
        byCategory: [], byPriority: [], recent: []
      },
      categoryMap: {
        electrical: '电气', plumbing: '水暖', furniture: '家具',
        door_window: '门窗', floor: '地面', wall: '墙面', other: '其他'
      },
      priorityMap: { low: '低', medium: '中', high: '高', urgent: '紧急' },
      statusMap: { pending: '待处理', processing: '处理中', completed: '已完成', rejected: '已驳回' },
      statusType: { pending: 'warning', processing: '', completed: 'success', rejected: 'danger' },
      priorityType: { low: 'info', medium: '', high: 'warning', urgent: 'danger' }
    }
  },
  mounted() {
    this.fetchData()
  },
  methods: {
    formatDate(dateStr) {
      if (!dateStr) return ''
      return new Date(dateStr).toLocaleString('zh-CN')
    },
    initCategoryChart(data) {
      const chart = echarts.init(this.$refs.categoryChartRef)
      chart.setOption({
        tooltip: { trigger: 'item' },
        series: [{
          type: 'pie',
          radius: ['40%', '70%'],
          data: data.map(item => ({
            name: this.categoryMap[item.category] || item.category,
            value: item.count
          })),
          label: { formatter: '{b}: {c}' }
        }]
      })
    },
    initPriorityChart(data) {
      const chart = echarts.init(this.$refs.priorityChartRef)
      chart.setOption({
        tooltip: {},
        xAxis: {
          type: 'category',
          data: data.map(item => this.priorityMap[item.priority] || item.priority)
        },
        yAxis: { type: 'value' },
        series: [{
          type: 'bar',
          data: data.map(item => item.count),
          itemStyle: {
            color: (params) => ['#909399', '#409eff', '#e6a23c', '#f56c6c'][params.dataIndex]
          }
        }]
      })
    },
    async fetchData() {
      try {
        const res = await maintenanceApi.getStatistics()
        if (res.code === 200) {
          this.stats = { ...this.stats, ...res.data }
          if (this.stats.byCategory.length) this.initCategoryChart(this.stats.byCategory)
          if (this.stats.byPriority.length) this.initPriorityChart(this.stats.byPriority)
        }
      } catch (e) {
        console.error(e)
      }
    }
  }
}
</script>

